const m = $('New inquiry').first().json
const text = String(m.text ?? '').slice(0, 4000)
const EMERGENCY = /\b(gas (smell|leak)|smell(s|ing)? (of )?gas|carbon monoxide|co (alarm|detector)|smoke|sparks?|sparking|on fire)\b/i
return [{ json: {
  from: m.from?.value?.[0]?.address ?? '', name: m.from?.value?.[0]?.name ?? '', subject: m.subject ?? '',
  text, threadId: m.threadId, emergency: EMERGENCY.test(m.subject + ' ' + text),
} }]

