// Take the tool call, then scan the draft in code: a prompt can be ignored,
// a regex cannot.
const res = $input.first().json
const call = (res.content ?? []).find((b) => b.type === 'tool_use')
if (!call) throw new Error('Claude returned no draft_reply tool call')
const d = call.input
const ctx = $('Emergency check').first().json
const flags = [
  [/\$\s?\d|\bper hour\b/i, 'mentions a price'],
  [/\bguarantee/i, 'makes a guarantee'],
  [/\b(within|in) (an?|one|two|\d+) (hours?|minutes?)\b|\bsame[- ]day\b/i, 'promises a time'],
].filter(([re]) => re.test(d.draft ?? '')).map(([, why]) => why)
return [{ json: { ...ctx, intent: d.intent, draft: d.draft ?? '', needsHuman: d.needs_human || flags.length > 0, flags: flags.join(', ') } }]
